-- ============================================================================
-- Hoppaz: the "Emergency Room" room template (emergency-room), layout rows for both widths.
-- GENERATED by scripts/crew-room/export-layouts.mjs --only emergency-room --out supabase/emergency_room_template.sql
-- from src/lib/campaign/templates.ts. Do not edit by hand: change the room, run the script, load the file.
--
-- Run order: after crew_rooms.sql AND crew_rooms_scale.sql. Then, once the owner has signed up, setup_emergencyroom.sql.
-- Safe to run twice (and as often as you like): it only inserts or refreshes the emergency-room rows. It touches no other
-- template, no room, no walker and no function.
-- Re-run rule: crew_rooms.sql puts the old slow helpers back and says so; run crew_rooms_scale.sql after it. Your emergency-room
-- rows survive both, but running this file again after them is harmless and re-checks the grids.
--
-- What it does: one transaction. It inserts the layout of emergency-room at widths 30 and 36 (the walls and furniture as
-- blocks, the zones, the spawn). crew_rooms_scale.sql keeps a trigger on crew_room_layouts that fills the ready-made walk grid
-- (walk) and the area look-up (area_at) from that data on every insert and update, so no extra step is needed; the last
-- statement checks they were filled and that the spawn and every zone stop are walkable tiles. A crew picks the template in
-- MANAGE CREW (crew_room_set_template) once these rows exist.
-- ============================================================================
begin;
set local lock_timeout = '3s';

do $guard$
begin
  if to_regclass('public.crew_room_layouts') is null or to_regprocedure('public.crew_room_set_template(uuid,text)') is null then
    raise exception 'emergency-room: crew_rooms.sql must be loaded first';
  end if;
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'crew_room_layouts' and column_name = 'walk')
     or not exists (select 1 from pg_trigger where tgrelid = 'public.crew_room_layouts'::regclass and tgname = 'crew_room_layout_grids' and not tgisinternal) then
    raise exception 'emergency-room: crew_rooms_scale.sql must be loaded first (it keeps the walk grid of each layout)';
  end if;
end $guard$;

insert into public.crew_room_layouts(template,width,data) values
('emergency-room',30,'{"grid":{"width":30,"height":20,"tile":32},"spawn":{"x":15,"y":17},"zones":[{"id":"stage","name":"THE DECK","subtitle":"DJ is on","material":"stagedeck","x":10,"y":7,"w":10,"h":7,"stop":{"x":14,"y":13},"plaque":{"x":13,"y":13},"number":"01"},{"id":"entrance","name":"ENTRANCE","subtitle":"Tickets here","material":"concrete","x":14,"y":14,"w":9,"h":5,"stop":{"x":18,"y":18},"plaque":{"x":18,"y":18},"number":"02"},{"id":"experiences","name":"EXPERIENCES","subtitle":"Follow on Instagram","material":"concrete","x":2,"y":7,"w":5,"h":6,"stop":{"x":4,"y":12},"plaque":{"x":4,"y":12},"link":{"label":"OPEN INSTAGRAM","url":"https://www.instagram.com/emergencyroombysos/"},"number":"03"},{"id":"healing","name":"AFROTECH HEALING","subtitle":"Sit back, breathe","material":"concrete","x":2,"y":13,"w":5,"h":6,"stop":{"x":4,"y":18},"plaque":{"x":4,"y":18},"number":"04"},{"id":"merch","name":"MERCH","subtitle":"The drip","material":"concrete","x":23,"y":7,"w":5,"h":6,"stop":{"x":25,"y":12},"plaque":{"x":25,"y":12},"number":"05"},{"id":"hall-of-fame","name":"HALL OF FAME","subtitle":"Past nights and awards","material":"concrete","x":9,"y":2,"w":12,"h":5,"stop":{"x":14,"y":6},"plaque":{"x":14,"y":6},"number":"06"},{"id":"performers","name":"PERFORMERS ON DUTY","subtitle":"Next event''s DJs","material":"concrete","x":2,"y":2,"w":6,"h":5,"stop":{"x":5,"y":6},"plaque":{"x":5,"y":6},"number":"07"}],"privateAreas":[],"blocks":[{"x":1,"y":1,"w":28,"h":3},{"x":1,"y":4,"w":1,"h":15},{"x":28,"y":4,"w":1,"h":15},{"id":"er-sign","kind":"erlightbox","x":22,"y":1,"w":6,"h":3,"solid":true},{"id":"hall-of-fame","kind":"ravehall","x":9,"y":1,"w":12,"h":3,"solid":true},{"id":"doctors-on-duty","kind":"performers","x":2,"y":1,"w":6,"h":3,"solid":true},{"id":"main-stage","kind":"hub","x":13,"y":8,"w":4,"h":4,"solid":true},{"id":"hub-speaker-l","kind":"erspeaker","x":11,"y":8,"w":1,"h":3,"solid":true},{"id":"hub-speaker-r","kind":"erspeaker","x":18,"y":8,"w":1,"h":3,"solid":true},{"id":"courtyard-fountain","kind":"fountain","x":14,"y":12,"w":2,"h":1,"solid":true},{"id":"brand-page","kind":"experiences","x":2,"y":7,"w":5,"h":4,"solid":true},{"id":"recovery","kind":"healing","x":2,"y":13,"w":5,"h":4,"solid":true},{"id":"merch","kind":"merchrack","x":23,"y":7,"w":5,"h":4,"solid":true},{"id":"tickets-desk","kind":"entrancedesk","x":16,"y":14,"w":4,"h":3,"solid":true},{"id":"plant-r1","kind":"plant","x":24,"y":13,"w":1,"h":1,"solid":true},{"id":"plant-r2","kind":"plant","x":26,"y":14,"w":1,"h":1,"solid":true},{"id":"lounge-bench","kind":"erbench","x":23,"y":15,"w":3,"h":1,"solid":true},{"id":"gate-plant-l","kind":"plant","x":10,"y":17,"w":1,"h":1,"solid":true},{"id":"gate-plant-r","kind":"plant","x":22,"y":17,"w":1,"h":1,"solid":true},{"id":"entry-map-table","kind":"ergate","x":13,"y":16,"w":2,"h":1,"solid":true}]}'::jsonb),
('emergency-room',36,'{"grid":{"width":36,"height":20,"tile":32},"spawn":{"x":18,"y":17},"zones":[{"id":"stage","name":"THE DECK","subtitle":"DJ is on","material":"stagedeck","x":13,"y":7,"w":10,"h":7,"stop":{"x":17,"y":13},"plaque":{"x":16,"y":13},"number":"01"},{"id":"entrance","name":"ENTRANCE","subtitle":"Tickets here","material":"concrete","x":17,"y":14,"w":9,"h":5,"stop":{"x":21,"y":18},"plaque":{"x":21,"y":18},"number":"02"},{"id":"experiences","name":"EXPERIENCES","subtitle":"Follow on Instagram","material":"concrete","x":2,"y":7,"w":5,"h":6,"stop":{"x":4,"y":12},"plaque":{"x":4,"y":12},"link":{"label":"OPEN INSTAGRAM","url":"https://www.instagram.com/emergencyroombysos/"},"number":"03"},{"id":"healing","name":"AFROTECH HEALING","subtitle":"Sit back, breathe","material":"concrete","x":2,"y":13,"w":5,"h":6,"stop":{"x":4,"y":18},"plaque":{"x":4,"y":18},"number":"04"},{"id":"merch","name":"MERCH","subtitle":"The drip","material":"concrete","x":29,"y":7,"w":5,"h":6,"stop":{"x":31,"y":12},"plaque":{"x":31,"y":12},"number":"05"},{"id":"hall-of-fame","name":"HALL OF FAME","subtitle":"Past nights and awards","material":"concrete","x":12,"y":2,"w":12,"h":5,"stop":{"x":17,"y":6},"plaque":{"x":17,"y":6},"number":"06"},{"id":"performers","name":"PERFORMERS ON DUTY","subtitle":"Next event''s DJs","material":"concrete","x":2,"y":2,"w":6,"h":5,"stop":{"x":5,"y":6},"plaque":{"x":5,"y":6},"number":"07"}],"privateAreas":[],"blocks":[{"x":1,"y":1,"w":34,"h":3},{"x":1,"y":4,"w":1,"h":15},{"x":34,"y":4,"w":1,"h":15},{"id":"er-sign","kind":"erlightbox","x":28,"y":1,"w":6,"h":3,"solid":true},{"id":"hall-of-fame","kind":"ravehall","x":12,"y":1,"w":12,"h":3,"solid":true},{"id":"doctors-on-duty","kind":"performers","x":2,"y":1,"w":6,"h":3,"solid":true},{"id":"main-stage","kind":"hub","x":16,"y":8,"w":4,"h":4,"solid":true},{"id":"hub-speaker-l","kind":"erspeaker","x":14,"y":8,"w":1,"h":3,"solid":true},{"id":"hub-speaker-r","kind":"erspeaker","x":21,"y":8,"w":1,"h":3,"solid":true},{"id":"courtyard-fountain","kind":"fountain","x":17,"y":12,"w":2,"h":1,"solid":true},{"id":"brand-page","kind":"experiences","x":2,"y":7,"w":5,"h":4,"solid":true},{"id":"recovery","kind":"healing","x":2,"y":13,"w":5,"h":4,"solid":true},{"id":"merch","kind":"merchrack","x":29,"y":7,"w":5,"h":4,"solid":true},{"id":"tickets-desk","kind":"entrancedesk","x":19,"y":14,"w":4,"h":3,"solid":true},{"id":"plant-r1","kind":"plant","x":30,"y":13,"w":1,"h":1,"solid":true},{"id":"plant-r2","kind":"plant","x":32,"y":14,"w":1,"h":1,"solid":true},{"id":"lounge-bench","kind":"erbench","x":29,"y":15,"w":3,"h":1,"solid":true},{"id":"gate-plant-l","kind":"plant","x":13,"y":17,"w":1,"h":1,"solid":true},{"id":"gate-plant-r","kind":"plant","x":25,"y":17,"w":1,"h":1,"solid":true},{"id":"entry-map-table","kind":"ergate","x":16,"y":16,"w":2,"h":1,"solid":true}]}'::jsonb)
on conflict(template,width) do update set data=excluded.data;

-- The grids are kept by the trigger; refuse to commit if they are not there or the room cannot be walked.
do $verify$
declare
  l record;
  z jsonb;
  tiles int;
begin
  for l in select * from public.crew_room_layouts where template = 'emergency-room' loop
    if l.gw is null or l.gh is null or l.walk is null or l.area_at is null
       or char_length(l.walk) <> l.gw * l.gh or coalesce(array_length(l.area_at, 1), 0) <> l.gw * l.gh then
      raise exception 'emergency-room at width %: the walk grid is missing or the wrong size', l.width;
    end if;
    if substr(l.walk, (l.data->'spawn'->>'y')::int * l.gw + (l.data->'spawn'->>'x')::int + 1, 1) <> '1' then
      raise exception 'emergency-room at width %: the spawn is not a walkable tile', l.width;
    end if;
    for z in select * from jsonb_array_elements(l.data->'zones') loop
      if substr(l.walk, (z->'stop'->>'y')::int * l.gw + (z->'stop'->>'x')::int + 1, 1) <> '1' then
        raise exception 'emergency-room at width %: the stop of zone % is not a walkable tile', l.width, z->>'id';
      end if;
    end loop;
    tiles := char_length(replace(l.walk, '0', ''));
    if tiles < 120 then raise exception 'emergency-room at width %: only % walkable tiles', l.width, tiles; end if;
    raise notice 'emergency-room at width %: % x % tiles, % walkable', l.width, l.gw, l.gh, tiles;
  end loop;
  if (select count(*) from public.crew_room_layouts where template = 'emergency-room') <> 2 then
    raise exception 'emergency-room: expected 2 layout rows';
  end if;
end $verify$;

commit;
